-- Study Abroad country content, BATCH 16: Mongolia, Fiji, Brunei, Cambodia, Maldives.
-- Researched from public sources in November 2026 (see backend/TODO_country_tables.md for what still needs checking).
-- Text blocks fill the columns on countries; subject / course rows are linked to subjects / specializations
-- (country_sections.subject_id / specialization_id) so the website links them to those pages.
-- Replaces the earlier '[Sample]' / '[Placeholder]' rows of these 5 countries. Safe to re-run.
-- Requires alembic revision e6a3c9d1f4b7 (alembic upgrade head).
BEGIN;
DELETE FROM country_sections WHERE country_id IN (SELECT id FROM countries WHERE slug IN ('mongolia', 'fiji', 'brunei', 'cambodia', 'maldives'));
UPDATE countries SET why_title = 'Why study in Mongolia?', why_body = '<p>Mongolia offers low-cost degrees, English-taught programmes at the National University of Mongolia and a six-year medical doctor degree at the Mongolian National University of Medical Sciences.</p><ul><li>Low tuition and living costs</li><li>English-taught options at leading universities</li><li>Medical doctor degree at MNUMS</li><li>Unique culture and landscapes</li></ul>', visa_title = 'Student visa requirements', visa_body = '<p>Students need an <strong>S (student) visa</strong> before arriving, then a residence permit after arrival. MNUMS says visa processing for in-person programmes can take up to 12 weeks.</p><ul><li>Admission letter from the university</li><li>Passport, photographs and medical certificate</li><li>Apply for the residence permit after arrival</li><li>Students must not take part-time jobs on a student visa and permit</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Mongolian embassy and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university. The National University of Mongolia publishes regulations on admission of international students.</p><ul><li>Academic transcripts and certificates</li><li>English proficiency proof (IELTS or TOEFL)</li><li>High school diploma and minimum age of 18 for medicine</li><li>Motivation letter for postgraduate programmes</li><li>Passport copy and photographs</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Third-party guides list National University of Mongolia international tuition; the academic year is not named.</p><ul><li>Bachelor''s: about MNT 10,500,000 a year; Master''s: about MNT 10,360,000; doctorate: MNT 11,200,000; Mongolian language course: MNT 9,187,500 (two guides agree, unconfirmed for 2026)</li><li>MNUMS medicine tuition was not found</li><li>Living costs: about US$250-$500 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate; medicine needs biology and chemistry</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> IELTS or TOEFL for English-taught programmes</li></ul>' WHERE slug = 'mongolia';
UPDATE countries SET why_title = 'Why study in Fiji?', why_body = '<p>Fiji is the education hub of the Pacific, home to the University of the South Pacific (USP) and Fiji National University, with strengths in tourism, marine science, agriculture and education.</p><ul><li>Regional university (USP) shared by Pacific island nations</li><li>Strong in tourism, marine and environmental science</li><li>English-medium teaching</li><li>Tropical lifestyle</li></ul>', visa_title = 'Student permit requirements', visa_body = '<p>Non-citizens need a <strong>Student Permit</strong>, applied for from outside Fiji through the ImmiHub portal once an offer is accepted. Visa-free entry does not allow study.</p><ul><li>Offer of admission from a Fijian institution</li><li>Base fee reported at FJD 321 (FJD 136 application plus FJD 185 issue)</li><li>Standard processing reported at 21 working days</li><li>Students cannot work on a student permit</li><li>Regional students who overstayed need PI Uplift approval first</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Fiji Ministry of Immigration and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>USP application steps: online admission application, offer, student permit, accommodation, orientation. USP semesters started on 23 February and 20 July 2026.</p><ul><li>Academic transcripts and certificates</li><li>English proficiency proof</li><li>Statement of purpose for postgraduate programmes</li><li>Passport copy and photographs</li><li>Application fee (FNU reports FJD 50 per form from 1 August 2026)</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Non-member-country citizens pay international fees.</p><ul><li>USP (2026, Laucala): a bachelor''s degree is about FJD 18,000 a year in tuition, plus field trip fees; Foundation about FJD 16,650 a year</li><li>USP Intensive English: FJD 3,600 per term (2026 schedule) or FJD 3,500 on the programme page</li><li>FNU and University of Fiji publish 2026 fee structures; check international rates</li><li>Living costs: about US$500-$900 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate or equivalent with required subjects</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> IELTS 6.0-6.5 or equivalent for most programmes</li></ul>' WHERE slug = 'fiji';
UPDATE countries SET why_title = 'Why study in Brunei?', why_body = '<p>Brunei offers small, high-quality universities, English-medium teaching and generous government scholarships for international students through the BDGS programme.</p><ul><li>Universiti Brunei Darussalam (UBD) with English-medium degrees</li><li>Government of Brunei scholarship for foreign students (BDGS)</li><li>Safe, wealthy country with a calm campus life</li><li>Strong in Islamic studies, business and sciences</li></ul>', visa_title = 'Student pass requirements', visa_body = '<p>You need a confirmed admission offer before applying for a <strong>student pass and visa</strong> through the institution. Exchange students receive endorsement from the International Students Unit and a visa on arrival converted within two weeks.</p><ul><li>Confirmed offer from a Bruneian institution</li><li>Passport, photographs and medical report</li><li>Exchange student visa fees reported at BND 20 (single entry) to BND 50 (multiple entry); check your own category</li><li>Immigration rules change, so confirm with the Immigration Department and the university</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Brunei Immigration Department and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to the university; UBD and UTB use online portals. BDGS applications also go through the university portal.</p><ul><li>Academic transcripts and certificates</li><li>IELTS or TOEFL proof</li><li>Statement of purpose for postgraduate programmes</li><li>Passport copy and photographs</li><li>Application and acceptance fee (BND 100, non-refundable if you do not register)</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>UBD''s official undergraduate page lists international fees; older sources differ.</p><ul><li>UBD registration fee for international students: BND 16,500 (BND 18,500 for lab-based Bachelor''s programmes)</li><li>BND 100 acceptance fee; a refundable BND 250 programme deposit is reported for 2026-27</li><li>BDGS scholarship covers tuition, flights and allowances (reported BND 500 a month personal and BND 150 for meals)</li><li>Living costs: about US$500-$900 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with required subjects</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> IELTS 6.0-6.5 or equivalent for English-medium programmes</li></ul>' WHERE slug = 'brunei';
UPDATE countries SET why_title = 'Why study in Cambodia?', why_body = '<p>Cambodia offers low-cost private and public university options, English-medium programmes and a growing economy, with strengths in business, hospitality and IT.</p><ul><li>English-medium programmes at private universities</li><li>Low living costs</li><li>Growing business and tourism sectors</li><li>Close to Thailand and Vietnam</li></ul>', visa_title = 'Student visa and extension', visa_body = '<p>Cambodia does not appear to issue a separate student visa from abroad. Students enter on an ordinary <strong>E visa</strong> and extend it in Cambodia as an <strong>ES student extension</strong> for 1, 3, 6 or 12 months.</p><ul><li>University acceptance or enrolment letter</li><li>Proof of funds</li><li>Government extension application fee reported at about USD 50 (aggregator, unconfirmed); agency prices are higher</li><li>Processing reported at 2-4 weeks</li><li>Renew each year with a fresh school letter</li><li>Work needs a separate work permit applied for by the employer</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Cambodian immigration (evisa.gov.kh) and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university.</p><ul><li>Academic transcripts and certificates</li><li>English proficiency proof</li><li>Motivation letter for postgraduate programmes</li><li>Passport copy and photographs</li><li>Entrance test at some universities</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>RUPP and other public universities'' fees were not found in the search.</p><ul><li>Private universities: check each university; fees are set per programme</li><li>Living costs: about US$250-$500 a month (estimate)</li><li>ES extension costs recur each year</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with good results</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English proof for English-medium programmes</li></ul>' WHERE slug = 'cambodia';
UPDATE countries SET why_title = 'Why study in the Maldives?', why_body = '<p>The Maldives offers tourism, hospitality and marine-related study in a small island nation, with the Maldives National University (MNU) as the main public provider.</p><ul><li>Hospitality, tourism and culinary programmes</li><li>Marine and environmental topics</li><li>English-medium teaching</li><li>Unique island setting</li></ul>', visa_title = 'Student visa requirements', visa_body = '<p>MNU directs students to apply for a <strong>Student Visa (IM23)</strong> through the IMUGA immigration portal. Once approved and on arrival, students have 30 days to complete the student visa application.</p><ul><li>Admission letter from the university</li><li>Medical report as part of the application</li><li>Approved health and travel insurance for the visa period</li><li>A stay on a student visa lasts one academic year and is renewed afterwards</li><li>Official pages do not say that a student visa permits paid work</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Maldives Immigration (IMUGA) and MNU site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to the university. MNU''s international admissions requirements are not clearly published in the pages found.</p><ul><li>Academic transcripts and certificates</li><li>English proficiency proof</li><li>Motivation letter for postgraduate programmes</li><li>Passport copy and photographs</li><li>Contact the international student helpdesk in writing for specifics</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>MNU course pages state the fees for local students and say international students pay <strong>twice</strong> the fee. A study guide says the helpdesk told them it is <strong>five times</strong> for student-visa holders, so ask MNU in writing which rule applies.</p><ul><li>International rate: 2x the published local fee (MNU course pages) or 5x (helpdesk report, unconfirmed)</li><li>Insurance is compulsory</li><li>Living costs: about US$600-$1,200 a month (estimate; island prices are high)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with good results</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English proof for English-medium programmes</li></ul>' WHERE slug = 'maldives';
COMMIT;
